?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= e($pageTitle) ?> - <?= e(APP_NAME) ?></title><link rel="stylesheet" href="assets/css/style.css"><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css"></head><body><?php include __DIR__.'/includes/header.php'; ?><?php include __DIR__.'/includes/sidebar.php'; ?><main class="main-content"><div class="page-title"><span class="eyebrow">FUND YOUR ACCOUNT</span><h1>Deposits</h1><p class="muted">All deposits are simulated for development and testing.</p></div><div class="quick-grid"><a class="quick-card accent" href="confirm-deposit.php"><i class="fas fa-arrow-down-to-bracket"></i><strong>Manual deposit</strong><span>Submit a payment reference</span></a><a class="quick-card" href="package.php"><i class="fas fa-box-open"></i><strong>Buy a package</strong><span>Use your wallet balance</span></a></div><section class="panel"><div class="section-heading"><h2>Deposit history</h2></div><?php if(!$deposits): ?><p class="empty">No deposits submitted yet.</p><?php else: ?><div class="table-wrap"><table><thead><tr><th>Amount</th><th>Method</th><th>Reference</th><th>Status</th><th>Date</th></tr></thead><tbody><?php foreach($deposits as $d): ?><tr><td><?= formatCurrency($d['amount']) ?></td><td><?= e($d['payment_method']) ?></td><td><?= e($d['payment_reference'] ?: '—') ?></td><td><span class="badge <?= e($d['status']) ?>"><?= e(ucfirst($d['status'])) ?></span></td><td><?= e(formatDate($d['created_at'])) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section></main><?php include __DIR__.'/includes/bottom-nav.php'; ?><?php include __DIR__.'/includes/footer.php'; ?><script src="assets/js/app.js"></script></body></html>
